describe('observedAlertRuleProjectionToValue', () => {
  const value = {
    uid: 'value-uid',
    name: 'value-name',
    trigger: 'value-trigger',
    origin: { $ref: 'ref-origin' },
    minLevel: 'value-minLevel',
    threshold: 'value-threshold',
    windowMinutes: 'value-windowMinutes',
    channel: 'value-channel',
    target: 'value-target',
    cooldownMinutes: 'value-cooldownMinutes',
    mutedUntil: 'value-mutedUntil',
    enabled: 'value-enabled',
    version: 'value-version',
  } as any;

  it('returns null without projection', () => {
    expect(observedAlertRuleProjectionToValue(null)).toBeNull();
    expect(observedAlertRuleProjectionToValue(undefined)).toBeNull();
  });

  it('keeps a plain value', () => {
    expect(observedAlertRuleProjectionToValue(value)).toEqual(value);
  });

  it('reduces the projected references to their key', () => {
    const projection = {
      uid: 'value-uid',
      name: 'value-name',
      trigger: 'value-trigger',
      origin: () => ({ uid: 'ref-origin' }),
      minLevel: 'value-minLevel',
      threshold: 'value-threshold',
      windowMinutes: 'value-windowMinutes',
      channel: 'value-channel',
      target: 'value-target',
      cooldownMinutes: 'value-cooldownMinutes',
      mutedUntil: 'value-mutedUntil',
      enabled: 'value-enabled',
      version: 'value-version',
    } as any;
    expect(observedAlertRuleProjectionToValue(projection)).toEqual(value);
  });
});
